use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    match timeout(deadline, run(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut sum: u64 = 0;
    let mut ids = ids.into_iter();
    loop {
        let wave: Vec<u32> = ids.by_ref().take(4).collect();
        if wave.is_empty() {
            return Ok(sum);
        }
        let futures: Vec<_> = wave
            .iter()
            .map(|&id| {
                let fetch = fetch.clone();
                async move { (id, fetch.fetch(id).await.map_err(|_| id)) }
            })
            .collect();
        let results = join_all_bounded(4, futures).await;
        for (id, result) in results {
            match result {
                Ok(value) => sum += value,
                Err(id) => return Err(SolveError::Fetch { id }),
            }
        }
    }
}

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::{timeout, Elapsed};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let work = async {
        let mut join_set: JoinSet<Result<u64, u32>> = JoinSet::new();
        let mut ids_iter = ids.into_iter();
        let mut sum: u64 = 0;
        let mut spawned: usize = 0;
        let total = 0; // not needed; we track by spawning until no more ids and set empty

        // Spawn first up to 4 tasks
        let mut limit_spawned = 0;
        let max_in_flight = 4;
        while limit_spawned < max_in_flight {
            match ids_iter.next() {
                Some(id) => {
                    let fetcher = fetch.clone();
                    join_set.spawn(async move {
                        match fetcher.fetch(id).await {
                            Ok(v) => Ok(v),
                            Err(_) => Err(id),
                        }
                    });
                    spawned += 1;
                    limit_spawned += 1;
                }
                None => break,
            }
        }

        // Process results; if any task fails, return Fetch with that id (and remaining tasks
        // are aborted when JoinSet is dropped)
        loop {
            match join_set.join_next().await {
                Some(Ok(result)) => match result {
                    Ok(v) => {
                        sum = sum.saturating_add(v);
                        // If there are more ids to fetch, spawn next one
                        if let Some(id) = ids_iter.next() {
                            let fetcher = fetch.clone();
                            join_set.spawn(async move {
                                match fetcher.fetch(id).await {
                                    Ok(v) => Ok(v),
                                    Err(_) => Err(id),
                                }
                            });
                            // continue loop to wait for next completion
                        } else if join_set.is_empty() {
                            // No more work to spawn and no tasks in flight
                            return Ok(sum);
                        } else {
                            // No more ids to spawn; just wait for remaining to complete
                        }
                    }
                    Err(failing_id) => {
                        // Fetch failed for this id; abort remaining and return Fetch
                        return Err(SolveError::Fetch { id: failing_id });
                    }
                },
                Some(Err(_join_err)) => {
                    // Join error from task; treat as cancelled per task semantics
                    return Err(SolveError::Cancelled);
                }
                None => {
                    // JoinSet is empty - all done
                    return Ok(sum);
                }
            }
        }
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(Elapsed) => Err(SolveError::Deadline),
    }
}

use lgwks_bot::rt::sync::Semaphore;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;
use std::sync::Arc;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let sem = Arc::new(Semaphore::new(4));
    let fetch = Arc::new(fetch);
    let mut ids_iter = ids.into_iter();
    let mut set: JoinSet<(u32, Result<u64, ai_task_support::FetchError>)> = JoinSet::new();

    // Spawn initial up to 4 tasks
    let mut spawned = 0;
    while spawned < 4 {
        if let Some(id) = ids_iter.next() {
            let sem = sem.clone();
            let fetch = fetch.clone();
            set.spawn(async move {
                let _permit = sem.acquire().await;
                let res = fetch.fetch(id).await;
                (id, res)
            });
            spawned += 1;
        } else {
            break;
        }
    }

    let mut sum: u64 = 0;
    let mut done_spawning = ids_iter.next().is_none();

    // Run with deadline
    let result = timeout(deadline, async {
        loop {
            // If no tasks left and nothing to spawn, we're done
            if set.is_empty() && done_spawning {
                return Ok(sum);
            }

            // Join next completed task
            if let Some(task_res) = set.join_next().await {
                match task_res {
                    Ok((id, fetch_res)) => match fetch_res {
                        Ok(val) => {
                            sum = sum.saturating_add(val);
                            // Spawn next if available
                            if !done_spawning {
                                if let Some(next_id) = ids_iter.next() {
                                    let sem = sem.clone();
                                    let fetch = fetch.clone();
                                    set.spawn(async move {
                                        let _permit = sem.acquire().await;
                                        let res = fetch.fetch(next_id).await;
                                        (next_id, res)
                                    });
                                } else {
                                    done_spawning = true;
                                }
                            }
                            // Continue loop
                        }
                        Err(_) => {
                            // Failure observed - abort remaining tasks and return Fetch error for this id
                            set.abort_all();
                            return Err(SolveError::Fetch { id });
                        }
                    },
                    Err(_) => {
                        // Task was aborted (panic/cancel) - treat as cancelled due to drop context
                        set.abort_all();
                        return Err(SolveError::Cancelled);
                    }
                }
            } else {
                // JoinSet empty
                if done_spawning {
                    return Ok(sum);
                }
            }
        }
    })
    .await;

    match result {
        Ok(inner_res) => inner_res,
        Err(_) => {
            // Deadline exceeded
            set.abort_all();
            Err(SolveError::Deadline)
        }
    }
}

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    use lgwks_bot::rt::task::join_all_bounded;
    use lgwks_bot::rt::time::{timeout_at, Instant};

    let deadline_at = Instant::now().checked_add(deadline);
    let mut total: u64 = 0;

    for chunk in ids.chunks(4) {
        if let Some(dl) = deadline_at {
            if Instant::now() >= dl {
                return Err(SolveError::Deadline);
            }
        }

        let wave = chunk.iter().map(|&id| {
            let fetcher = fetch.clone();
            async move { (id, fetcher.fetch(id).await) }
        });

        let outcomes = match deadline_at {
            Some(dl) => match timeout_at(dl, join_all_bounded(4, wave)).await {
                Ok(outcomes) => outcomes,
                Err(_) => return Err(SolveError::Deadline),
            },
            None => join_all_bounded(4, wave).await,
        };

        for (id, outcome) in outcomes {
            match outcome {
                Ok(value) => total += value,
                Err(_) => return Err(SolveError::Fetch { id }),
            }
        }
    }

    Ok(total)
}

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    match timeout(deadline, run(ids, fetch)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut set: JoinSet<(u32, Result<u64, ()>)> = JoinSet::new();
    let mut remaining = ids.into_iter();
    let mut sum: u64 = 0;

    for _ in 0..MAX_IN_FLIGHT {
        if !spawn_one(&mut set, &mut remaining, &fetch) {
            break;
        }
    }

    while let Some(outcome) = set.join_next().await {
        match outcome {
            Ok((id, Ok(value))) => {
                sum = sum.wrapping_add(value);
                spawn_one(&mut set, &mut remaining, &fetch);
            }
            Ok((id, Err(()))) => {
                set.abort_all();
                return Err(SolveError::Fetch { id });
            }
            Err(_join_error) => {
                set.abort_all();
                return Err(SolveError::Cancelled);
            }
        }
    }

    Ok(sum)
}

fn spawn_one(
    set: &mut JoinSet<(u32, Result<u64, ()>)>,
    remaining: &mut std::vec::IntoIter<u32>,
    fetch: &Fetcher,
) -> bool {
    match remaining.next() {
        Some(id) => {
            let fetch = fetch.clone();
            let _ = set.spawn(async move { (id, fetch.fetch(id).await.map_err(|_| ())) });
            true
        }
        None => false,
    }
}

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

async fn run_waves(
    tasks: &mut lgwks_bot::rt::task::JoinSet<Result<u64, u32>>,
    ids: Vec<u32>,
    fetch: &ai_task_support::Fetcher,
) -> Result<u64, SolveError> {
    let mut pending = ids.into_iter();
    let mut total: u64 = 0;

    loop {
        let mut launched: usize = 0;
        while launched < MAX_IN_FLIGHT {
            let id = match pending.next() {
                Some(id) => id,
                None => break,
            };
            let fetcher = fetch.clone();
            tasks.spawn(async move { fetcher.fetch(id).await.map_err(|_| id) });
            launched += 1;
        }

        if launched == 0 {
            return Ok(total);
        }

        let mut remaining = launched;
        while remaining > 0 {
            match tasks.join_next().await {
                Some(Ok(Ok(value))) => {
                    total = total.wrapping_add(value);
                    remaining -= 1;
                }
                Some(Ok(Err(id))) => return Err(SolveError::Fetch { id }),
                Some(Err(_join_error)) => return Err(SolveError::Cancelled),
                None => remaining = 0,
            }
        }
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    let mut tasks: lgwks_bot::rt::task::JoinSet<Result<u64, u32>> =
        lgwks_bot::rt::task::JoinSet::new();

    let raced =
        lgwks_bot::rt::time::timeout(deadline, run_waves(&mut tasks, ids, &fetch)).await;

    tasks.abort_all();

    match raced {
        Ok(result) => result,
        Err(_elapsed) => Err(SolveError::Deadline),
    }
}

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::task::{Context, Poll};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::time::sleep;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let mut iter = ids.into_iter();
    let mut in_flight: Vec<Pin<Box<dyn Future<Output = Result<u64, SolveError>> + Send>>> =
        Vec::new();
    let mut sum: u64 = 0;
    let mut deadline_fut: Pin<Box<dyn Future<Output = ()> + Send>> = Box::pin(sleep(deadline));

    poll_fn(|cx: &mut Context<'_>| -> Poll<Result<u64, SolveError>> {
        if deadline_fut.as_mut().poll(cx).is_ready() {
            in_flight.clear();
            return Poll::Ready(Err(SolveError::Deadline));
        }

        loop {
            while in_flight.len() < 4 {
                match iter.next() {
                    Some(id) => {
                        let f = fetch.clone();
                        let fut: Pin<
                            Box<dyn Future<Output = Result<u64, SolveError>> + Send>,
                        > = Box::pin(async move {
                            match f.fetch(id).await {
                                Ok(value) => Ok(value),
                                Err(_) => Err(SolveError::Fetch { id }),
                            }
                        });
                        in_flight.push(fut);
                    }
                    None => break,
                }
            }

            let mut progressed = false;
            let mut index = 0;
            while index < in_flight.len() {
                match in_flight[index].as_mut().poll(cx) {
                    Poll::Ready(Ok(value)) => {
                        sum = sum.wrapping_add(value);
                        in_flight.swap_remove(index);
                        progressed = true;
                    }
                    Poll::Ready(Err(error)) => {
                        in_flight.clear();
                        return Poll::Ready(Err(error));
                    }
                    Poll::Pending => index += 1,
                }
            }

            if !progressed {
                break;
            }
        }

        if in_flight.is_empty() {
            Poll::Ready(Ok(sum))
        } else {
            Poll::Pending
        }
    })
    .await
}

use std::time::Duration;

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    if deadline.is_zero() {
        return Err(SolveError::Deadline);
    }

    match timeout(deadline, run(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: ai_task_support::Fetcher) -> Result<u64, SolveError> {
    let mut set = JoinSet::new();
    let mut pending = ids.into_iter();
    let mut in_flight: usize = 0;
    let mut total: u64 = 0;

    while in_flight < 4 {
        match pending.next() {
            Some(id) => {
                let fetch = fetch.clone();
                let _ = set.spawn(async move {
                    let result = fetch.fetch(id).await;
                    (id, result)
                });
                in_flight += 1;
            }
            None => break,
        }
    }

    while in_flight > 0 {
        match set.join_next().await {
            None => break,
            Some(Err(_)) => return Err(SolveError::Cancelled),
            Some(Ok((id, result))) => {
                in_flight -= 1;
                match result {
                    Ok(value) => {
                        total += value;
                        if let Some(next) = pending.next() {
                            let fetch = fetch.clone();
                            let _ = set.spawn(async move {
                                let result = fetch.fetch(next).await;
                                (next, result)
                            });
                            in_flight += 1;
                        }
                    }
                    Err(_) => return Err(SolveError::Fetch { id }),
                }
            }
        }
    }

    Ok(total)
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn fetch(stage: Stage, name: StageName) -> Result<Artifact, StageError> {
    stage.run(name).await
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = async move {
        let futures = vec![
            fetch(stage.clone(), StageName::FetchA),
            fetch(stage.clone(), StageName::FetchB),
        ];

        let mut results = join_all_bounded(2, futures).await.into_iter();

        let a = results.next().expect("one result per fetch");
        let b = results.next().expect("one result per fetch");

        if a.is_err() {
            return Err(PipelineError::Stage {
                name: StageName::FetchA,
            });
        }
        if b.is_err() {
            return Err(PipelineError::Stage {
                name: StageName::FetchB,
            });
        }

        if stage.run(StageName::Combine).await.is_err() {
            return Err(PipelineError::Stage {
                name: StageName::Combine,
            });
        }

        match stage.run(StageName::Publish).await {
            Ok(artifact) => Ok(Published::from(artifact)),
            Err(_) => Err(PipelineError::Stage {
                name: StageName::Publish,
            }),
        }
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    match timeout(deadline, run(ids, fetch)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    const LIMIT: usize = 4;

    let mut set = JoinSet::new();
    let mut pending = ids.into_iter();
    let mut sum: u64 = 0;
    let mut in_flight: usize = 0;

    while in_flight < LIMIT {
        match pending.next() {
            Some(id) => {
                let fetch = fetch.clone();
                let _ = set.spawn(async move { (id, fetch.fetch(id).await) });
                in_flight += 1;
            }
            None => break,
        }
    }

    while in_flight > 0 {
        match set.join_next().await {
            Some(Ok((_, Ok(value)))) => {
                sum = sum.wrapping_add(value);
            }
            Some(Ok((id, Err(_)))) => {
                set.abort_all();
                return Err(SolveError::Fetch { id });
            }
            Some(Err(_)) => {}
            None => break,
        }

        in_flight -= 1;

        if let Some(id) = pending.next() {
            let fetch = fetch.clone();
            let _ = set.spawn(async move { (id, fetch.fetch(id).await) });
            in_flight += 1;
        }
    }

    Ok(sum)
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};

use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn attempt(
    stage: Stage,
    run_name: StageName,
    error_name: StageName,
) -> Result<Artifact, PipelineError> {
    match stage.run(run_name).await {
        Ok(artifact) => Ok(artifact),
        Err(_) => Err(PipelineError::Stage { name: error_name }),
    }
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let work = async move {
        let fetches = vec![
            attempt(stage.clone(), StageName::FetchA, StageName::FetchA),
            attempt(stage.clone(), StageName::FetchB, StageName::FetchB),
        ];

        for result in join_all_bounded(2, fetches).await {
            if let Err(error) = result {
                return Err(error);
            }
        }

        stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

        let artifact = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

        Ok(Published::from(artifact))
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn run_stage(stage: Stage, name: StageName) -> Result<Artifact, StageError> {
    stage.run(name).await
}

pub async fn solve(
    stage: Stage,
    deadline: std::time::Duration,
) -> Result<Published, PipelineError> {
    let pipeline = async {
        let fetches = vec![
            run_stage(stage.clone(), StageName::FetchA),
            run_stage(stage.clone(), StageName::FetchB),
        ];

        let mut results = join_all_bounded(2, fetches).await.into_iter();

        results
            .next()
            .expect("fetch_a result")
            .map_err(|_| PipelineError::Stage { name: StageName::FetchA })?;

        results
            .next()
            .expect("fetch_b result")
            .map_err(|_| PipelineError::Stage { name: StageName::FetchB })?;

        stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

        let artifact = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

        Ok::<Published, PipelineError>(Published::from(artifact))
    };

    match timeout(deadline, pipeline).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let mut set: JoinSet<(StageName, Result<Artifact, ()>)> = JoinSet::new();

    let sa = stage.clone();
    set.spawn(async move {
        let result = sa.run(StageName::FetchA).await.map_err(|_| ());
        (StageName::FetchA, result)
    });
    let sb = stage.clone();
    set.spawn(async move {
        let result = sb.run(StageName::FetchB).await.map_err(|_| ());
        (StageName::FetchB, result)
    });

    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;
    while let Some(outcome) = set.join_next().await {
        match outcome {
            Ok((StageName::FetchA, Ok(artifact))) => a = Some(artifact),
            Ok((StageName::FetchB, Ok(artifact))) => b = Some(artifact),
            Ok((name, Err(()))) => {
                set.abort_all();
                return Err(PipelineError::Stage { name });
            }
            Ok(_) => {}
            Err(_) => {
                set.abort_all();
                return Err(PipelineError::Cancelled);
            }
        }
    }

    if a.is_none() || b.is_none() {
        return Err(PipelineError::Cancelled);
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

    Ok(Published::from(published))
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

enum FetchReport {
    A(bool),
    B(bool),
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(outcome) => outcome,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    fetch_both(&stage).await?;

    let _combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let artifact = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(artifact))
}

async fn fetch_both(stage: &Stage) -> Result<(), PipelineError> {
    let mut tasks: JoinSet<FetchReport> = JoinSet::new();

    let fetch_a_stage = stage.clone();
    let _ = tasks.spawn(async move { FetchReport::A(fetch_a_stage.run(StageName::FetchA).await.is_ok()) });

    let fetch_b_stage = stage.clone();
    let _ = tasks.spawn(async move { FetchReport::B(fetch_b_stage.run(StageName::FetchB).await.is_ok()) });

    let mut a_ok = false;
    let mut b_ok = false;
    let mut failure: Option<StageName> = None;

    while let Some(joined) = tasks.join_next().await {
        match joined {
            Ok(FetchReport::A(true)) => a_ok = true,
            Ok(FetchReport::B(true)) => b_ok = true,
            Ok(FetchReport::A(false)) => {
                if failure.is_none() {
                    failure = Some(StageName::FetchA);
                }
                tasks.abort_all();
            }
            Ok(FetchReport::B(false)) => {
                if failure.is_none() {
                    failure = Some(StageName::FetchB);
                }
                tasks.abort_all();
            }
            Err(_join_error) => {
                tasks.abort_all();
            }
        }
    }

    if let Some(name) = failure {
        return Err(PipelineError::Stage { name });
    }
    if a_ok && b_ok {
        return Ok(());
    }
    if !a_ok {
        return Err(PipelineError::Stage {
            name: StageName::FetchA,
        });
    }
    Err(PipelineError::Stage {
        name: StageName::FetchB,
    })
}

use ai_task_support::{Artifact, Published, Stage, StageName};

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

enum Which {
    A,
    B,
}

pub async fn solve(
    stage: Stage,
    deadline: std::time::Duration,
) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let mut set: JoinSet<Result<(Which, Artifact), PipelineError>> = JoinSet::new();

    {
        let stage_a = stage.clone();
        let _ = set.spawn(async move {
            let artifact = stage_a
                .run(StageName::FetchA)
                .await
                .map_err(|_| PipelineError::Stage {
                    name: StageName::FetchA,
                })?;
            Ok((Which::A, artifact))
        });

        let stage_b = stage.clone();
        let _ = set.spawn(async move {
            let artifact = stage_b
                .run(StageName::FetchB)
                .await
                .map_err(|_| PipelineError::Stage {
                    name: StageName::FetchB,
                })?;
            Ok((Which::B, artifact))
        });
    }

    let mut fetched_a = false;
    let mut fetched_b = false;

    while let Some(report) = set.join_next().await {
        match report {
            Ok(Ok((Which::A, _artifact))) => fetched_a = true,
            Ok(Ok((Which::B, _artifact))) => fetched_b = true,
            Ok(Err(error)) => {
                set.abort_all();
                return Err(error);
            }
            Err(_join_error) => {
                set.abort_all();
                return Err(PipelineError::Cancelled);
            }
        }
    }

    set.abort_all();

    if !(fetched_a && fetched_b) {
        return Err(PipelineError::Cancelled);
    }

    match stage.run(StageName::Combine).await {
        Ok(_combined) => {}
        Err(_) => {
            return Err(PipelineError::Stage {
                name: StageName::Combine,
            });
        }
    }

    match stage.run(StageName::Publish).await {
        Ok(artifact) => Ok(Published::from(artifact)),
        Err(_) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
    }
}
